import{_ as a,o,c as t,a2 as n}from"./chunks/framework.lxr64Vqo.js";const h=JSON.parse('{"title":"True Cloud Sync & 24/7 Standby","description":"","frontmatter":{},"headers":[],"relativePath":"guide/cloud-sync.md","filePath":"guide/cloud-sync.md","lastUpdated":1795114725000}'),r={name:"guide/cloud-sync.md"};function i(s,e,d,l,c,u){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="true-cloud-sync-24-7-standby" tabindex="-1">True Cloud Sync &amp; 24/7 Standby <a class="header-anchor" href="#true-cloud-sync-24-7-standby" aria-label="Permalink to &quot;True Cloud Sync &amp; 24/7 Standby&quot;">​</a></h1><p>NoxMedia is designed to run silently in the background as an always-available home media server, keeping your watch states and library synchronized across all your screens.</p><hr><h2 id="true-cloud-sync" tabindex="-1">True Cloud Sync <a class="header-anchor" href="#true-cloud-sync" aria-label="Permalink to &quot;True Cloud Sync&quot;">​</a></h2><p>Whether you watch on an Apple TV in your living room, an iPad in bed, or your computer via Nuvio, NoxMedia keeps your viewing session unified:</p><ul><li><strong>Resume Playback</strong>: Pause on Infuse or Vesper on Apple TV, resume at the exact second on your phone or desktop via Nuvio.</li><li><strong>Watched &amp; Unwatched States</strong>: Marking an episode or movie as watched reflects everywhere automatically.</li><li><strong>Cross-Device Scrobbling</strong>: Supports Jellyfin watch session reporting and optional Trakt scrobbling.</li></ul><hr><h2 id="_24-7-background-standby-hosting" tabindex="-1">24/7 Background Standby Hosting <a class="header-anchor" href="#_24-7-background-standby-hosting" aria-label="Permalink to &quot;24/7 Background Standby Hosting&quot;">​</a></h2><p>Android power management can sometimes suspend background processes. NoxMedia includes built-in safeguards to maintain an uninterrupted server uptime:</p><h3 id="_1-low-overhead-foreground-service" tabindex="-1">1. Low-Overhead Foreground Service <a class="header-anchor" href="#_1-low-overhead-foreground-service" aria-label="Permalink to &quot;1. Low-Overhead Foreground Service&quot;">​</a></h3><p>When the server toggle is enabled, NoxMedia launches an Android Foreground Service with a persistent notification, ensuring the operating system does not terminate the process.</p><h3 id="_2-battery-optimization-exemption" tabindex="-1">2. Battery Optimization Exemption <a class="header-anchor" href="#_2-battery-optimization-exemption" aria-label="Permalink to &quot;2. Battery Optimization Exemption&quot;">​</a></h3><p>For 24/7 reliability (especially when using an old phone or TV box as a dedicated server):</p><ol><li>Navigate to your device&#39;s <strong>Settings</strong> -&gt; <strong>Apps</strong> -&gt; <strong>NoxMedia</strong>.</li><li>Select <strong>Battery</strong> -&gt; Choose <strong>Unrestricted</strong> (or &quot;Don&#39;t Optimize&quot;).</li><li>Disable manufacturer-specific task killers (such as Xiaomi MIUI/HyperOS Autostart or Samsung Put to Sleep).</li></ol><h3 id="_3-wi-fi-power-management" tabindex="-1">3. Wi-Fi Power Management <a class="header-anchor" href="#_3-wi-fi-power-management" aria-label="Permalink to &quot;3. Wi-Fi Power Management&quot;">​</a></h3><p>Ensure your host device stays connected to Wi-Fi while sleeping:</p><ul><li>Keep the device connected to a power supply when acting as a permanent home hub.</li><li>In advanced Wi-Fi settings, set Wi-Fi sleep policy to <strong>Always on during sleep</strong>.</li></ul>',17)])])}const g=a(r,[["render",i]]);export{h as __pageData,g as default};
